1	import { test } from "node:test";
2	import assert from "node:assert/strict";
3	import { paginate } from "../lib/paginate.js";
4	
5	const rows = Array.from({ length: 25 }, (_, i) => ({ id: i + 1 }));
6	const letters = [
7	  { name: "c", n: 3 },
8	  { name: "a", n: 1 },
9	  { name: "b", n: 2 },
10	];
11	
12	test("page 1 returns the first perPage items", () => {
13	  const out = paginate(rows, { page: 1, perPage: 10 });
14	  assert.equal(out.items.length, 10);
15	  assert.equal(out.items[0].id, 1);
16	  assert.equal(out.items[9].id, 10);
17	});
18	
19	test("page 2 returns the next perPage items", () => {
20	  const out = paginate(rows, { page: 2, perPage: 10 });
21	  assert.equal(out.items[0].id, 11);
22	  assert.equal(out.items.length, 10);
23	});
24	
25	test("last partial page returns the remainder", () => {
26	  const out = paginate(rows, { page: 3, perPage: 10 });
27	  assert.equal(out.items.length, 5);
28	  assert.equal(out.items[4].id, 25);
29	  assert.equal(out.hasNext, false);
30	});
31	
32	test("hasPrev/hasPrev flags", () => {
33	  assert.equal(paginate(rows, { page: 1 }).hasPrev, false);
34	  assert.equal(paginate(rows, { page: 2 }).hasPrev, true);
35	  assert.equal(paginate(rows, { page: 2, perPage: 10 }).hasNext, true);
36	});
37	
38	test("out-of-range page is empty but well-formed", () => {
39	  const out = paginate(rows, { page: 99, perPage: 10 });
40	  assert.deepEqual(out.items, []);
41	  assert.equal(out.hasNext, false);
42	  assert.equal(out.hasPrev, true);
43	  assert.equal(out.total, 25);
44	});
45	
46	test("sortKey sorts ascending before paginating", () => {
47	  const out = paginate(letters, { page: 1, perPage: 2, sortKey: "n" });
48	  assert.deepEqual(out.items.map((x) => x.name), ["a", "b"]);
49	});
50	
51	test("per-item contract on tiny inputs", () => {
52	  const out = paginate([1], { page: 1, perPage: 10 });
53	  assert.deepEqual(out.items, [1]);
54	  assert.equal(out.hasNext, false);
55	});

