  const source = sortKey ? [...items].sort((a, b) => a[sortKey] - b[sortKey]) : items;

  // page is 1-indexed, so page 1 starts at offset 0; slice's end is exclusive.
  const start = (page - 1) * perPage;
  const end = start + perPage;
  const inRange = page >= 1 && start < source.length;

  return {
    items: inRange ? source.slice(start, Math.min(end, source.length)) : [],
    page,
    perPage,
    total: source.length,
    hasPrev: page > 1,
    hasNext: inRange && end < source.length,
  };
}
